b = assign['count_tennis_rackets']
c = assign['count_fountain_pen']
d = assign['count_hiking_backpack']
t2 = assign['exact_two']
t3 = assign['exact_three']
t4 = assign['exact_four']
# Basic domain checks
if N <= 0:
    return (False, None)
for x in [a,b,c,d,t2,t3,t4]:
    if x < 0:
        return (False, None)
    if x > N:
        return (False, None)
S_sum = a + b + c + d
# Sum across single sets cannot exceed 4N
if S_sum > 4*N:
    return (False, None)
# With notebook universal, exactly k of five maps to exactly (k-1) among the four non-universal items.
