if num < 0:
    return (False, None)
if num % 4 != 0:
    return (False, None)
e4 = num // 4
# Additional feasibility checks: e0 >= 0 and nontrivial hardness constraints
e_total = t2 + t3 + t4 + e4
e0 = N - e_total
if e0 < 0:
    return (False, None)
# Enforce nontriviality/difficulty: require at least 5 residents owning all five
if e4 < 5:
    return (False, None)
# Also require each of t2,t3,t4 positive to avoid trivial edge cases
if t2 <= 0 or t3 <= 0 or t4 <= 0:
    return (False, None)
answer = e4
